import { Uri, ExtensionContext } from 'vscode';
import * as cheerio from 'cheerio';
import { join } from 'path';
import PluginsManager from './PluginsManager';
import { getNonce, isURL } from './utils';

export default class ContentProvider {
  public static getContent(context: ExtensionContext, content?: string | undefined) {
    const plugins = PluginsManager.getAll();
    const pluginsFiles = plugins.map(({ path }) => {
      const p = path || '';

      return !isURL(p) ? Uri.file(p).with({ scheme: 'vscode-resource' }) : p;
    });
    const vendorsUri = Uri.file(
      join(context.extensionPath, '/out/ui/vendors.bundle.js')
    ).with({ scheme: 'vscode-resource' });
    const grapesUri = Uri.file(join(context.extensionPath, '/out/ui/grapes.min.js')).with({
      scheme: 'vscode-resource'
    });
    const scriptUri = Uri.file(join(context.extensionPath, '/out/ui/app.bundle.js')).with({
      scheme: 'vscode-resource'
    });

    const nonce = getNonce();

    return `<!DOCTYPE html>
						<html lang="en">
						<head>
							<meta charset="UTF-8">

							<!--
							Use a content security policy to only allow loading images from https or from our extension directory,
							and only allow scripts that have a specific nonce.
							-->
							<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src 'self' data: vscode-resource: https: http:; style-src 'unsafe-inline' vscode-resource: https: http:; script-src 'nonce-${nonce}' 'unsafe-eval' https: http:; font-src 'self' data: 'unsafe-inline' vscode-resource: https: http:;">

							<meta name="viewport" content="width=device-width, initial-scale=1.0">
							<title>GrapesJS</title>
							<script nonce="${nonce}" src="${vendorsUri}"></script>
							<script nonce="${nonce}" src="${grapesUri}"></script>
							${pluginsFiles
                .map(
                  plugin =>
                    `<script nonce="${nonce}" src="${plugin ? plugin : ''}"></script>`
                )
                .join('')}
							<script nonce="${nonce}">
								window.plugins = ${JSON.stringify(plugins.map(plugin => (plugin ? plugin.name : '')))}
								window.pluginsOptions = ${JSON.stringify(
                  plugins.map(plugin =>
                    plugin ? { options: plugin.options, name: plugin.name } : {}
                  )
                )}
							</script>
						</head>
						<body>
							<div id="root">								
								<div class="editor-row">
									<div class="editor-canvas">
										<div id="gjs">
											${content || this.getTemplate()}
										</div>
									</div>
									<div class="panel__right">
										<div class="panel__switcher"></div>
										<div class="panel__content">
											<div class="layers-container"></div>
											<div class="styles-container" style="display: none;"></div>
											<div class="traits-container" style="display: none;"></div>
											<div class="blocks-container" style="display: none;"></div>
										</div>
										<div class="panel__basic-actions"></div>
									</div>
								</div>
							</div>
							<script nonce="${nonce}" src="${scriptUri}"></script>
						</body>
						</html>`;
  }

  public static exportMockup(html: string, css: string) {
    let mockup;

    if (this._isHeadInHtml(html)) {
      mockup = html;
    } else {
      mockup = `<!DOCTYPE html>
			<html lang="en">
				<head>
					<meta charset="UTF-8">
					<meta name="viewport" content="width=device-width, initial-scale=1.0">
					<title></title>
				</head>
				<body>${html}</body>
			</html>`;
    }

    return this._addCssInHtml(mockup, css);
  }

  private static getTemplate() {
    return `<!DOCTYPE html>
		<html>
			<head>
				<link href="https://fonts.googleapis.com/css?family=Signika&display=swap" rel="stylesheet">
				<style>
					html, body {
						margin: 0;
						padding: 0;
						height: 100%;
					}
					body {
						position: relative;
						font-family: Arial, Helvetica, sans-serif;
						background: linear-gradient(#101452 10%, #131862 55%, #546bab);
					}
					.jumbotron {
						margin: 0;
						padding: 50px;
						position: absolute;
						top: 50%;
						left: 50%;
						transform: translate(-50%, -50%);
						border-radius: 25%;
						color: #fff;
					}
					.jumbotron h1 {
						font-family: 'Signika', sans-serif;
						text-transform: uppercase;
						text-shadow: 0 0 5px #fff, 0 0 10px #fff, 0 0 20px #ff0080, 0 0 30px #ff0080, 0 0 40px #ff0080;
					}
					.text-center {
						text-align: center;
					}
				</style>
			</head>
			<body>
				<div class="jumbotron">
					<h1 class="text-center">Ready to Build <br/>with GrapesJS&nbsp;!!!</h1>
				</div>
			</body>
		</html>`;
  }

  private static _isHeadInHtml(html: string) {
    const $ = cheerio.load(html);

    return $('head').length > 0;
  }

  private static _addCssInHtml(html: string, css: string) {
    const $ = cheerio.load(html);

    $('head').append(`<style>${css}</style>`);

    return $.html();
  }
}

import * as vscode from 'vscode';
import Manager from './Manager';

export function activate(context: vscode.ExtensionContext) {
  context.subscriptions.push(
    vscode.commands.registerCommand('grapesjs.showPanel', () => {
      Manager.createOrShow(context);
    })
  );
  context.subscriptions.push(
    vscode.commands.registerCommand('grapesjs.export', () => {
      Manager.exportContent();
    })
  );

  if (vscode.window.registerWebviewPanelSerializer) {
    vscode.window.registerWebviewPanelSerializer(Manager.viewType, {
      async deserializeWebviewPanel(webviewPanel: vscode.WebviewPanel, state: any) {
        console.log(`Got state: ${state}`);
        Manager.revive(webviewPanel, context);
      }
    });
  }
}

export function deactivate() {}

import * as vscode from 'vscode';
import ContentProvider from './ContentProvider';

let timerId: NodeJS.Timeout;

export default class GrapesEditorManager {
  public static currentPanel: GrapesEditorManager | undefined;
  public static viewFocus = 'grapesjsViewFocus';
  public static viewType = 'grapesjs.editor';
  private readonly _panel: vscode.WebviewPanel;
  private _activeEditor: vscode.TextEditor | undefined;
  private _disposables: vscode.Disposable[] = [];

  public static createOrShow(context: vscode.ExtensionContext) {
    if (GrapesEditorManager.currentPanel) {
      const activeEditor = vscode.window.activeTextEditor;
      const activeContent =
        activeEditor &&
        GrapesEditorManager.isAcceptableLaguage(activeEditor.document.languageId)
          ? activeEditor.document.getText()
          : '';
      const { _panel } = GrapesEditorManager.currentPanel;

      _panel.reveal(vscode.ViewColumn.Two);
      _panel.webview.postMessage({
        command: 'loading'
      });

      if (timerId) clearTimeout(timerId);

      timerId = setTimeout(() => {
        _panel.webview.postMessage({
          command: 'change',
          content: activeContent
        });
      }, 300);
    } else {
      const panel = vscode.window.createWebviewPanel(
        GrapesEditorManager.viewType,
        'Grapesjs Editor',
        vscode.ViewColumn.Two,
        {
          enableScripts: true,
          retainContextWhenHidden: true
        }
      );

      GrapesEditorManager.currentPanel = new GrapesEditorManager(panel, context);
    }
  }

  public static exportContent() {
    if (GrapesEditorManager.currentPanel) {
      GrapesEditorManager.currentPanel._panel.webview.postMessage({
        command: 'callExport'
      });
    }
  }

  public static revive(panel: vscode.WebviewPanel, context: vscode.ExtensionContext) {
    GrapesEditorManager.currentPanel = new GrapesEditorManager(panel, context);
  }

  public static isAcceptableLaguage(languageId: string) {
    return languageId === 'html';
  }

  private onChangeTextDocument(event: vscode.TextDocumentChangeEvent) {
    const { document, contentChanges } = event;

    if (
      this._activeEditor &&
      GrapesEditorManager.isAcceptableLaguage(document.languageId) &&
      contentChanges.length > 0
    ) {
      const content = document.getText();

      this._panel.webview.postMessage({
        command: 'change',
        content
      });
    }
  }

  private constructor(panel: vscode.WebviewPanel, context: vscode.ExtensionContext) {
    const config: vscode.WorkspaceConfiguration = vscode.workspace.getConfiguration();
    const delay: number = config.get('grapesjs.delay') || 0;
    const activeEditor = vscode.window.activeTextEditor;
    const activeContent =
      activeEditor &&
      GrapesEditorManager.isAcceptableLaguage(activeEditor.document.languageId)
        ? activeEditor.document.getText()
        : '';
    this._panel = panel;
    this._panel.onDidDispose(() => this.dispose(), null, this._disposables);
    this._panel.onDidChangeViewState(({ webviewPanel }) => {
      this.setWebviewActiveContext(webviewPanel.active);
    });
    this._panel.webview.html = ContentProvider.getContent(context, activeContent);
    this._panel.webview.onDidReceiveMessage(
      message => {
        switch (message.command) {
          case 'export':
            const { html, css } = message.content;

            vscode.workspace
              .openTextDocument({
                language: 'html',
                content: ContentProvider.exportMockup(html, css)
              })
              .then(doc =>
                vscode.window.showTextDocument(doc, {
                  preserveFocus: true
                })
              );
            return;
        }
      },
      null,
      this._disposables
    );

    this.setWebviewActiveContext(true);

    if (activeEditor) {
      this._activeEditor = activeEditor;
    }

    vscode.workspace.onDidChangeTextDocument((event: vscode.TextDocumentChangeEvent) => {
      const { document, contentChanges } = event;

      if (
        this._activeEditor &&
        GrapesEditorManager.isAcceptableLaguage(document.languageId) &&
        contentChanges.length > 0
      ) {
        this._panel.webview.postMessage({
          command: 'loading'
        });

        if (timerId) clearTimeout(timerId);

        timerId = setTimeout(() => {
          this.onChangeTextDocument(event);
        }, delay);
      }
    });
  }

  public dispose() {
    GrapesEditorManager.currentPanel = undefined;
    this._panel.dispose();
    while (this._disposables.length) {
      const x = this._disposables.pop();
      if (x) {
        x.dispose();
      }
    }
  }

  public setWebviewActiveContext(value: boolean) {
    vscode.commands.executeCommand('setContext', GrapesEditorManager.viewFocus, value);
  }
}

import * as vscode from 'vscode';
import * as fs from 'fs';
import { resolve } from 'path';
import { getNestedObject, isURL } from './utils';

export default class PluginsManager {
  public static getAll() {
    if (!vscode.workspace.workspaceFolders) return [];

    const pluginsFolderPath: string =
      vscode.workspace.getConfiguration().get('grapesjs.pluginsFolder') || './';
    const workspaceFolderPath = vscode.workspace.workspaceFolders[0].uri.fsPath;

    const srcPath = resolve(workspaceFolderPath, pluginsFolderPath);
    const pluginsFolders = this._getDirectories(srcPath);
    const pluginsConfig = pluginsFolders.map(folder =>
      this._getConfig(resolve(srcPath, folder))
    );

    return pluginsConfig
      .map((config, i) => {
        return config ? this._loadPlugin(resolve(srcPath, pluginsFolders[i]), config) : {};
      })
      .filter(this._validPlugin);
  }

  private static _getDirectories(srcPath: string) {
    return fs
      .readdirSync(srcPath)
      .filter(file => fs.statSync(resolve(srcPath, file)).isDirectory());
  }

  private static _getConfig(srcPath: string) {
    if (fs.existsSync(resolve(srcPath, 'package.json'))) {
      try {
        const contentConfig = fs
          .readFileSync(resolve(srcPath, 'package.json'))
          .toString('utf8');
        const jsonConfig = JSON.parse(contentConfig);

        return Object.assign(getNestedObject(jsonConfig, ['vscode', 'grapesjs']), {
          name: jsonConfig.name || '',
          main: jsonConfig.main || ''
        });
      } catch (err) {
        vscode.window.showErrorMessage(err.message || err);
      }
    }
  }

  private static _loadPlugin(
    srcPath: string,
    config: { lib: string; name: string; main: string; options?: any }
  ) {
    const { lib, name, main, options } = config;
    const p = lib || main;
    const path = !isURL(p) ? resolve(srcPath, p) : p;

    return fs.existsSync(path) || isURL(path) ? { options: options || {}, path, name } : {};
  }

  private static _validPlugin(plugin: any) {
    return plugin !== {} && plugin.hasOwnProperty('path') && plugin.hasOwnProperty('name');
  }
}

export function getNestedObject(nestedObj: any, pathArr: Array<string>) {
  return pathArr.reduce(
    (obj, key) => (obj && obj[key] !== 'undefined' ? obj[key] : undefined),
    nestedObj
  );
}

export function getNonce() {
  let text = '';
  const possible = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  for (let i = 0; i < 32; i++) {
    text += possible.charAt(Math.floor(Math.random() * possible.length));
  }
  return text;
}

export function isURL(str: string) {
  const urlRegex = '^(?:http|https|ftp)://';
  const url = new RegExp(urlRegex, 'i');
  return url.test(str);
}

