function initPluginsOptions(plugins) {
	return plugins.reduce((acc, curr) => {
		acc[curr.name] = curr.options;
		return acc
	}, {})
}

import { typeBlockCode } from './config';

export default (editor, opts = {}) => {
  const bm = editor.BlockManager;
  const { blockCustomCode, blockLabel } = opts;

  blockCustomCode &&
    bm.add(typeBlockCode, {
      label: blockLabel,
      attributes: { class: 'fa fa-code' },
      category: 'Extra',
      activate: true,
      select: true,
      content: { type: typeBlockCode },
      ...blockCustomCode
    });
};

import { commandName, keyBlockCode } from './config';

export default (editor, opts = {}) => {
  const cmd = editor.Commands;
  const { modalTitle, codeViewOptions } = opts;
  const appendToContent = (target, content) => {
    if (content instanceof HTMLElement) {
      target.appendChild(content);
    } else if (content) {
      target.insertAdjacentHTML('beforeend', content);
    }
  };

  cmd.add(commandName, {
    run(editor, sender, opts = {}) {
      this.editor = editor;
      this.options = opts;
      this.target = opts.target || editor.getSelected();

      const target = this.target;

      if (target && target.get('editable')) {
        this.showBlockCode(target);
      }
    },

    stop(editor) {
      editor.Modal.close();
    },

    showBlockCode(target) {
      const { editor, options } = this;
      const title = options.title || modalTitle;
      const content = this.getContent();

      let htmlContent = document.createElement('div');
      htmlContent.innerHTML = target.toHTML();
      htmlContent = htmlContent.firstChild.innerHTML;

      editor.Modal.open({ title, content })
        .getModel()
        .once('change:open', () => editor.stopCommand(this.id));
      this.getCodeViewer().setContent(htmlContent);
    },

    /**
     * Custom pre-content. Can be a simple string or an HTMLElement
     */
    getPreContent() {},

    /**
     * Custom post-content. Can be a simple string or an HTMLElement
     */
    getPostContent() {},

    /**
     * Get all the content for the custom code
     * @return {HTMLElement}
     */
    getContent() {
      const { editor } = this;
      const content = document.createElement('div');
      const codeViewer = this.getCodeViewer();
      const pfx = editor.getConfig('stylePrefix');
      content.className = `${pfx}custom-code`;
      appendToContent(content, this.getPreContent());
      content.appendChild(codeViewer.getElement());
      appendToContent(content, this.getPostContent());
      appendToContent(content, this.getContentActions());
      codeViewer.refresh();
      setTimeout(() => codeViewer.focus(), 0);

      return content;
    },

    getContentActions() {
      const { editor } = this;
      const btn = document.createElement('button');
      const pfx = editor.getConfig('stylePrefix');
      btn.innerHTML = opts.buttonLabel;
      btn.className = `${pfx}btn-prim ${pfx}btn-import__edit-block`;
      btn.onclick = () => this.handleSave();

      return btn;
    },

    handleSave() {
      const { editor, target } = this;
      const code = this.getCodeViewer().getContent();
      target.set(keyBlockCode, code);
      editor.Modal.close();
    },

    getCodeViewer() {
      const { editor } = this;

      if (!this.codeViewer) {
        this.codeViewer = editor.CodeManager.createViewer({
          codeName: 'htmlmixed',
          theme: 'hopscotch',
          readOnly: 0,
          ...codeViewOptions
        });
      }

      return this.codeViewer;
    }
  });
};

import { keyBlockCode, typeBlockCode, commandName } from './config';

export default (editor, opts = {}) => {
  let timedInterval;
  const comps = editor.DomComponents;
  const { toolbarBtnBlockCode } = opts;

  comps.addType('default', {
    model: {
      defaults: {
        editable: true
      },
      init() {
        this.listenTo(this, `change:${keyBlockCode}`, this.onBlockCodeChange);
        const initialCode = this.get(keyBlockCode) || '';
        !this.components().length && this.components(initialCode);
        const toolbar = this.get('toolbar');
        const id = 'block-code';

        toolbar.unshift({
          id,
          command: commandName,
          label: `<svg viewBox="0 0 24 24">
            <path d="M14.6 16.6l4.6-4.6-4.6-4.6L16 6l6 6-6 6-1.4-1.4m-5.2 0L4.8 12l4.6-4.6L8 6l-6 6 6 6 1.4-1.4z"></path>
          </svg>`,
          ...toolbarBtnBlockCode
        });
      },
      onBlockCodeChange() {
        this.components(this.get(keyBlockCode));
      }
    },

    view: {
      events: {
        dblClick: 'onActive'
      },

      init() {
        this.listenTo(this.model.components(), 'add remove reset', this.onComponentsChange);
        this.onComponentsChange();
      },

      onComponentsChange() {
        timedInterval && clearInterval(timedInterval);
        timedInterval = setTimeout(() => {
          const { model } = this;
          const content = model.get(keyBlockCode) || '';
          let droppable = 1;

          // Avoid rendering codes with scripts
          if (content.indexOf('<script') >= 0) {
            this.el.innerHTML = opts.placeholderScript;
            droppable = 0;
          }

          model.set({ droppable });
        }, 0);
      },

      onActive() {
        const target = this.model;
        this.em.get('Commands').run(commandName, { target });
      }
    }
  });

  comps.addType(typeBlockCode, {
    extend: 'default'
  });
};

